import{_ as a,o as r,c as i,S as t}from"./chunks/framework.D1Ss-Xl7.js";const A=JSON.parse('{"title":"vibe coding时代的软件开发","description":"软件开发进入了vibe coding时代，开发从农耕时代进入了工业化时代，就连写博客你打几个单词，AI都会自动帮你推测接下来要说的话。工程师失去了编程的快乐和成就感，也失去了对代码的掌控力。","frontmatter":{"title":"vibe coding时代的软件开发","date":"2026-11-23 10:16","comments":true,"archives":2026,"tags":["web"]},"headers":[],"relativePath":"posts/2026-11-23-vibe-coding/index.md","filePath":"posts/2026/2026-11-23-vibe-coding.md"}'),o={name:"posts/2026-11-23-vibe-coding/index.md"};function n(d,e,s,c,l,h){return r(),i("div",null,[...e[0]||(e[0]=[t('<p>软件开发进入了vibe coding时代，开发从农耕时代进入了工业化时代，就连写博客你打几个单词，AI都会自动帮你推测接下来要说的话。工程师失去了编程的快乐和成就感，也失去了对代码的掌控力。</p><h2 id="工程师的职责" tabindex="-1">工程师的职责 <a class="header-anchor" href="#工程师的职责" aria-label="Permalink to &quot;工程师的职责&quot;">​</a></h2><p>编程不再是单纯地写代码和实现功能，而是更关注需求能否被正确实现，以及如何与 AI 协作，保证最终结果符合预期。因此我们需要合理地约束 AI。 例如实现功能之前添加测试用例，确保功能实现符合预期。通过配置 AGENTS.md 文件，定义项目的开发规范，并且在开发过程中总结 AI 的使用经验并补充到文档中。</p><h2 id="code-review" tabindex="-1">code review <a class="header-anchor" href="#code-review" aria-label="Permalink to &quot;code review&quot;">​</a></h2><p>AI 降低了开发的门槛，可以快速地生成代码实现功能，但也带来了新的挑战。如何 review AI 生成的代码，是否每行代码都应该认真阅读，还是根据每个PR的内容和优先级来决定 review 的深度？ 我觉得这个问题没有标准答案，根据业务的不同，项目的复杂度以及团队的经验，实际操作起来完全不一样。例如我们现在就是用 Claude Code 来生成代码，然后使用 GitHub 的 Copilot 进行代码 review。之后再根据 AI 的 review 结果，人工 review 一次，来保证代码质量。</p><h2 id="ai-协作" tabindex="-1">AI 协作 <a class="header-anchor" href="#ai-协作" aria-label="Permalink to &quot;AI 协作&quot;">​</a></h2><p>在古法编程时代，人工协作是通过约定开发标准来保证不同水平的工程师有尽可能一致的代码风格和实现方式。而在 vibe coding 时代，AI 成为协作的一部分，我们如何保证不同工程师使用 AI 能够有相同质量的输出。 例如高级工程师有能力判断 AI 生成的代码质量是否符合项目规范和预期，而初级工程师依赖 AI 的辅助来编写代码，往往仅仅通过简单的测试就完成代码的验收，甚至不去关注代码质量，只要功能实现正确即可。这样会给项目开发引入隐患，因为 AI 还没有能力保证 100% 的高质量，代码目前还是不能完全当作是一个黑盒来判断。这时候其实是更想让初级工程师通过阅读 AI 生成的代码来快速提升自己的编码能力，而不是完全依赖 AI。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>AI 时代，软件开发的流程发生了深刻的变化。而且也在持续地变化，1年前的 AI 可能只能简单地完成某个功能和具体需求，现在的 AI 已经可以完成一个项目从0到1的构建和开发了。但是 AI 终究是辅助工具，最终判断和负责任的还是实际的工程师。作为一名工程师要时刻更新自己的知识和技能，保证在 AI 时代能跟上时代的脚步，一同成长，而不是把工作交给 AI 自己却放弃了思考。</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p><a href="https://cpojer.net/posts/modern-engineering-values" target="_blank" rel="noreferrer">Modern Engineering Values</a></p><p><a href="https://claude.dev/blog/solving-code-review-at-anthropic/" target="_blank" rel="noreferrer">How the Claude Code team does code review</a></p>',12)])])}const v=a(o,[["render",n]]);export{A as __pageData,v as default};
